+// Skeleton: the JS contract lives in ../index.ts. Real metering (AVAudioRecorder at 1 Hz, 10 s
+// 16 kHz mono 16-bit WAV spike clips, SoundAnalysis speech check) is a later issue.
+public class KipAudioModule: Module {
+  private var recording = false
+
+  public func definition() -> ModuleDefinition {
+    Name("KipAudio")
+
+    Events("onSample", "onSpike")
+
+    AsyncFunction("start") { (options: StartOptions) in
+      self.recording = true
+    }
+
+    AsyncFunction("stop") {
+      self.recording = false
+    }
+
+    Function("isRecording") {
+      return self.recording
+    }
+
+    AsyncFunction("deleteClip") { (uri: String) in
+      // Later issue: delete the WAV at `uri`.
+    }
+  }
+}
+
+struct StartOptions: Record {
+  @Field var spikeThresholdDb: Double = 0
+}
+import { requireNativeModule } from "expo";
+
+import type { KipAudioNative } from "./types";
+
+// Resolved from the Swift module `KipAudio`; throws in a build that does not link it.
+export default requireNativeModule<KipAudioNative>("KipAudio");
+import type { AudioSample, KipAudioNative, SpikeEvent, StartOptions } from "./types";
+
+// Development stub: every value is generated, never measured, and every payload has `simulated: true`.
+// No clips are produced: spikes are reported as `speechDropped` so no consumer gets a fake URI.
+const SPIKE_EVERY_SAMPLES = 20;
+
+const sampleListeners = new Set<(s: AudioSample) => void>();
+const spikeListeners = new Set<(s: SpikeEvent) => void>();
+let timer: ReturnType<typeof setInterval> | undefined;
+
+function startSimulation({ spikeThresholdDb }: StartOptions) {
+  let n = 0;
+  timer = setInterval(() => {
+    n += 1;
+    const isSpike = n % SPIKE_EVERY_SAMPLES === 0;
+    const relativeDb = isSpike ? spikeThresholdDb + 2 : Math.random() * 3 - 1.5;
+    const t = Date.now();
+    for (const cb of sampleListeners) cb({ t, relativeDb, simulated: true });
+    if (isSpike) {
+      for (const cb of spikeListeners)
+        cb({ t, peakDb: relativeDb, speechDropped: true, simulated: true });
+    }
+  }, 1000);
+}
+
+const module: KipAudioNative = {
+  async start(options) {
+    if (timer !== undefined) return;
+    console.warn("[kip-audio] web stub: emitting SIMULATED samples");
+    startSimulation(options);
+  },
+  async stop() {
+    if (timer !== undefined) clearInterval(timer);
+    timer = undefined;
+  },
+  isRecording: () => timer !== undefined,
+  async deleteClip() {},
+  addListener(event: "onSample" | "onSpike", cb: never) {
+    const set = (event === "onSample" ? sampleListeners : spikeListeners) as Set<typeof cb>;
+    set.add(cb);
+    return { remove: () => void set.delete(cb) };
+  },
+};
+
+export default module;
+// The frozen JS surface of kip-audio (docs/ARCHITECTURE.md, "Contracts"). Changing it needs a platform issue.
+
+/** Spike clips are 16 kHz mono 16-bit PCM WAV, so the server needs no audio decoder. */
+export const CLIP_FORMAT = {
+  sampleRateHz: 16_000,
+  channels: 1,
+  bitDepth: 16,
+  container: "wav",
+} as const;
+
+/** Seconds of audio kept around each spike (docs/DOMAIN.md, "Bedroom noise"). */
+export const CLIP_SECONDS = 10;
+
+export type StartOptions = {
+  /** Spike = level this many dB above the night's rolling median. Comes from `packages/shared`. */
+  spikeThresholdDb: number;
+};
+
+/** One metering sample, once a second. The phone mic is uncalibrated, so the level is relative dB only. */
+export type AudioSample = {
+  /** Unix epoch milliseconds. */
+  t: number;
+  /** Level in dB relative to the night's own baseline. Not calibrated SPL. */
+  relativeDb: number;
+  /** True when the value was generated by the web stub, never measured. */
+  simulated: boolean;
+};
+
+type SpikeBase = {
+  /** Unix epoch milliseconds of the peak. */
+  t: number;
+  /** Peak level in relative dB. */
+  peakDb: number;
+  simulated: boolean;
+};
+
+/**
+ * Either a clip was kept (`clipUri` points at a 16 kHz mono 16-bit WAV in app storage) or the
+ * on-device speech check dropped it (`speechDropped`, no audio exists). Never both.
+ */
+export type SpikeEvent =
+  | (SpikeBase & { clipUri: string; speechDropped?: false })
+  | (SpikeBase & { speechDropped: true; clipUri?: undefined });
+
+export type Unsubscribe = () => void;
+
+/** What each platform implementation (`KipAudioModule.ts` native, `.web.ts` stub) provides. */
+export type KipAudioNative = {
+  start(options: StartOptions): Promise<void>;
+  stop(): Promise<void>;
+  isRecording(): boolean;
+  deleteClip(uri: string): Promise<void>;
+  addListener(event: "onSample", cb: (s: AudioSample) => void): { remove(): void };
+  addListener(event: "onSpike", cb: (s: SpikeEvent) => void): { remove(): void };
+};

